<script setup>
import {ref,computed,watch,onMounted} from 'vue'
import {request} from './client'
import PaymentPeriod from './PaymentPeriod.vue'
import {monthWindow} from './paymentDates.js'
const props=defineProps({rooms:{type:Array,default:()=>[]},student:Boolean,revision:Array})
defineEmits(['pay','receipt'])
const range=ref(monthWindow()),status=ref('All'),page=ref(0),data=ref(null),busy=ref(false),error=ref('')
let sequence=0
async function load(){const run=++sequence;busy.value=true;error.value='';data.value=null;try{const result=await request('payment_reports','history',{...range.value,status:status.value,page:page.value});if(run===sequence)data.value=result}catch(e){if(run===sequence)error.value=e.message}finally{if(run===sequence)busy.value=false}}
function dates(value){range.value=value;page.value=0;load()}
watch([status,page],load);watch(()=>props.revision,()=>load());onMounted(load)
function filter(value){status.value=value;page.value=0}
const summary=computed(()=>{const groups={};for(const r of data.value?.totals||[]){const c=r.currency||'LKR';groups[c]||={paid:0,due:0};if(r.status==='Paid')groups[c].paid+=Number(r.amount);else if(!['Cancelled','Failed'].includes(r.status))groups[c].due+=Number(r.amount)}return Object.entries(groups)})
const money=(n,c='LKR')=>new Intl.NumberFormat('en-LK',{style:'currency',currency:c||'LKR'}).format(Number(n||0))
</script>
<template><section class="payment-history"><PaymentPeriod :busy="busy" @change="dates"/><p class="field-help">Filtered by invoice due date. Paid and outstanding totals cover all invoices due in this period; currencies stay separate.</p><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">Loading payment history…</p><template v-if="data"><p class="period-caption">{{data.start_date}} — {{data.end_date}}</p><div class="fee-period-totals"><article class="panel" v-for="[currency,sums] in summary" :key="currency"><span>Paid · {{currency}}</span><strong>{{money(sums.paid,currency)}}</strong><small>Outstanding: {{money(sums.due,currency)}}</small></article><p v-if="!summary.length">No invoices due in this period.</p></div><section class="panel"><h2>Payment history</h2><div class="tabs"><button v-for="s in ['All','Paid','Unpaid','Overdue']" :key="s" :class="{selected:status===s}" @click="filter(s)">{{s}}</button></div><div class="table-wrap"><table><thead><tr><th>Class / invoice</th><th>Due date</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="row in data.rows" :key="row.name"><td><strong>{{rooms.find(r=>r.name===row.classroom)?.title||row.classroom}}</strong><small>{{row.name}}</small></td><td>{{row.due_date}}</td><td>{{money(row.amount,row.currency)}}</td><td>{{row.review_pending?'Slip submitted · awaiting approval':row.status}}</td><td><button v-if="row.status==='Paid'" class="button subtle small" @click="$emit('receipt',row)">Receipt</button><button v-else-if="student&&!['Cancelled','Failed'].includes(row.status)" class="button primary small" @click="$emit('pay',row)">{{row.review_pending?'View submitted slip':'Upload payment slip'}}</button></td></tr></tbody></table></div><p v-if="!data.rows.length">No {{status==='All'?'':status.toLowerCase()}} invoices in this period.</p><div class="history-pager"><span>{{data.count}} invoices · Page {{page+1}}</span><button class="button subtle small" :disabled="!page||busy" @click="page--">Previous</button><button class="button subtle small" :disabled="(page+1)*25>=data.count||busy" @click="page++">Next</button></div></section></template></section></template>
<style scoped>.payment-history{margin:24px 0}.period-caption{font-size:12px;color:#674886;margin:16px 0}.fee-period-totals{display:flex;flex-wrap:wrap;gap:16px;margin-bottom:20px}.fee-period-totals article{flex:1;min-width:200px;display:grid;gap:12px;padding:22px}.fee-period-totals strong{font-size:26px;color:#482071}.payment-history>.panel{padding:22px}.payment-history h2{font-size:18px;margin-bottom:16px}td small{display:block;margin-top:5px;font-size:10px}.history-pager{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:18px}.history-pager>span{margin-right:auto;font-size:12px}</style>
